class MappedSectors(object):
    """Class for mapping sectors."""

    def __init__(self, executor):
        self.executor = executor
        self.get_sectors = self.executor.get_sectors
        self.get_ctrls = self.executor.get_ctrls
        self._mapped_sectors = None

    def get_mapped_sectors(self):
        """Keyword for getting sectors with mapped ctrl, enb, connection type and cell.
        Example mapped sectors output:
        {'1': {'cell': 1, 'enb': 1, 'connection': 'rf', 'ctrl': [1]},
         '2': {'cell': 2, 'enb': 1, 'connection': 'cpri', 'ctrl': [2]},
         '11': {'cell': 1, 'enb': 2, 'connection': 'obsai', 'ctrl': [3]}}

        :return: Dictionary with mapped sectors
        """
        sectors = self.get_sectors()
        ctrls = self.get_ctrls()
        enbs = []
        self._mapped_sectors = {sector_number: {} for sector_number in sectors}

        for sector_number in sectors:
            ctrl = self._add_ctrl(sector_number, ctrls)
            enb_number = self._add_enb(sectors, sector_number)
            if enb_number not in enbs:
                enbs.append(enb_number)
            self._add_connection(sectors, sector_number, ctrls, ctrl)
        self._add_cells(sectors, enbs)
        return self._mapped_sectors

    def _add_ctrl(self, sector_number, ctrls):
        """Add list of ctrls to map for proceeded sector.

        :param sector_number: Number of currently proceed sector
        :param ctrls: Dictionary with ctrls configurations
        :return: List of ctrls for currently proceeded sector
        """
        ctrl = []
        for ctrl_number in ctrls:
            ctrl_sector = str(ctrls[ctrl_number].get('sectors')).replace(',', '')
            if sector_number == ctrl_sector:
                ctrl.append(int(ctrl_number))
        self._mapped_sectors[sector_number]['ctrl'] = ctrl
        return ctrl

    def _add_enb(self, sectors, sector_number):
        """Add eNB number to map for proceeded sector.

        :param sectors: Dictionary with sectors configurations
        :param sector_number: Number of currently proceed sector
        :return: Number of eNB for proceeded sector
        """
        if sectors[sector_number].get('enb'):
            enb_number = sectors[sector_number].get('enb')
        else:
            enb_number = int(int(sector_number) / 10) + 1
        self._mapped_sectors[sector_number]['enb'] = enb_number
        return enb_number

    def _add_connection(self, sectors, sector_number, ctrls, ctrl):
        """Add connection method to map for proceeded sector.

        :param sectors: Dictionary with sectors configurations
        :param sector_number: Number of currently proceed sector
        :param ctrls: List of ctrls for currently proceeded sector
        :param ctrl: Dictionary with ctrls configurations
        :return: None
        """
        if sectors[sector_number].get('fzm_rf') == 'on':
            connection = 'rf'
        elif isinstance(sectors[sector_number].get('lbr'), int):
            connection = 'cpri'
        else:
            for ctrl_number in ctrl:
                if ctrls.get(str(ctrl_number)).get('fzm_rf') in ('on', 'true'):
                    connection = 'rf'
                    break
            else:
                connection = 'obsai'
        self._mapped_sectors[sector_number]['connection'] = connection

    def _add_cells(self, sectors, enbs):
        """Add cell number to map for all sectors.

        :param sectors: Dictionary with sectors configurations
        :param enbs: List of all eNBs' numbers
        :return: None
        """
        self._add_specified_cells(sectors, enbs)
        self._add_not_specified_cells()

    def _add_specified_cells(self, sectors, enbs):
        """Add cell number to map for sectors with specified eNB in configuration.

        :param sectors: Dictionary with sectors configurations
        :param enbs: List of all eNBs' numbers
        :return:
        """
        for enb_number in enbs:
            sorted_enb_sectors = self._get_sorted_enb_sectors(sectors, enb_number)
            for sector_number in sorted_enb_sectors:
                self._mapped_sectors[sector_number]['cell'] = sorted_enb_sectors.index(sector_number) + 1

    def _get_sorted_enb_sectors(self, sectors, enb_number):
        """Get list with sorted sectors for specified eNB.

        :param sectors: Dictionary with sectors configurations
        :param enb_number: Number of specified eNB
        :return: Sorted list of sectors' numbers
        """
        sorted_enb_sectors = []
        for sector_number in self._mapped_sectors:
            if sectors[sector_number].get('enb') == enb_number:
                sorted_enb_sectors.append(sector_number)
                sorted_enb_sectors.sort(key=int)
        return sorted_enb_sectors

    def _add_not_specified_cells(self):
        """Add cell number to map for sectors without specified eNB in configuration.

        :return: None
        """
        for sector_number in self._mapped_sectors:
            if self._mapped_sectors[sector_number].get('cell') is None:
                self._mapped_sectors[sector_number]['cell'] = \
                    int(sector_number) - (self._mapped_sectors[sector_number]['enb'] - 1) * 10
